 "research_concepts": [
  "lineup effects",
  "shot selection",
  "offensive strategy",
  "personnel effects",
  "shot mix",
  "shot distribution"
 ],
 "methodological_questions": [
  "causal inference for lineup changes",
  "confounding in basketball analytics",
  "measurement of shot distribution",
  "sample size for lineup analysis",
  "isolating lineup effects from other factors",
  "endogeneity of lineup choices"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-PAP-009",
   "status_as_recorded": "supported",
   "finding": "Lineup coverage (>=1 organizer, shaper, terminal) varies within team, is separable from talent/counts, and talent control behaves. G1 72 team-seasons with >=200 poss in both; G2 |rho(COVERED,TALENT)|=0.042, aux R2=0.203; G3 rho(TALENT,PPP)=+0.027. Gate passed."
  },
  {
   "id": "FAM:SF-TMP-009",
   "status_as_recorded": "artifact",
   "finding": "The PULL_UP-specific decline with exposure is defensive adaptation rather than shooter selection/lineup artifact. With lineup FE: slope holding shot fixed -0.0255 (0.0061); shooter's earlier scored -0.1044 vs not scored +0.0693. No lineup FE: -0.0063 (0.0036); placebo other play types -0.0075 (0.0017)."
  },
  {
   "id": "FAM:SF38",
   "status_as_recorded": "inconclusive",
   "finding": "An action gets less effective the more often the defense has already seen it in the game. League-wide within-game -0.0019 PPP/exposure (SE 0.0019); across-game +0.0004 (SE 0.0015); H1 exposures to H2 -0.0000 (SE 0.0024). After 5 exposures, effects >~0.02 ruled out. Only PULL_UP within-game -0.030 SE."
  },
  {
   "id": "FAM:SF34",
   "status_as_recorded": "inconclusive",
   "finding": "Offenses attack the rim more when the opponent has no big on the floor. DRIVE +0.82pp (SE 0.25 t=+3.3); POST_UP +0.43pp (SE 0.18 t=+2.4); 3PA -1.79pp (SE 0.31 t=-5.8); rim <=4ft +0.12pp (t=+0.4); PPP +0.008 (SE 0.007 t=+1.1)."
  },
  {
   "id": "FAM:SF-APPA-005",
   "status_as_recorded": "untestable",
   "finding": "Playoff defenses change scheme within games and between games, especially after the opponent ran a play type heavily. Within-game change 319/523 (61.0%); cross-game change 298/440 (67.7%); 103/104 units (99.0%) and 52/52 series show a change; transition matrices near-uniform."
  },
  {
   "id": "FAM:SF-TMP-016",
   "status_as_recorded": "untestable",
   "finding": "Teams differ reliably in how H1 play-type PPP moves H2 usage/persistence. Adaptation slope +0.1168 (0.0589); heterogeneity var +0.029821 vs null +0.014085 p=0.363; split-half r=-0.026 p=0.655; persistence split-half r=+0.067 p=0.251."
  },
  {
   "id": "FAM:SF-APPS-058",
   "status_as_recorded": "untestable",
   "finding": "NBA matchup/PBP fields can label on-ball coverage (DROP/ICE/SWITCH) at usable rates. DET: 67 on-ball HC poss, 10 labeled (14.9%) ? DROP n=5 PPP=1.20, ICE_CANDIDATE n=5 PPP=0.80, OTHER n=57 PPP=1.42. ORL: 60 poss, 2 labeled (3.3%). switches_on unpopulated."
  },
  {
   "id": "FAM:SF-APPM-021",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Describe how play-type mix shifts by halftime margin, crunch time and after runs. OTHER +2.26 to +2.48pp in H2 in every bucket; crunch OTHER +6.08pp, PULL_UP +1.20pp at -0.045 PPP; post-run DRIVE +3.75pp, OTHER -6.72pp."
  },
  {
   "id": "FAM:SF-PAP-007",
   "status_as_recorded": "supported",
   "finding": "Teams run more cuts/PNR and fewer spot-ups/drives when a shaper is on the floor. Shaper: CUT +1.353pp (sd 1.434), PNR +0.98pp, SPOT_UP -1.248pp, DRIVE -0.542pp; Organizer POST_UP +2.331pp"
  },
  {
   "id": "FAM:SF-PAP-008",
   "status_as_recorded": "inconclusive",
   "finding": "Shaper presence increases non-focal play-type diversity (entropy). d_entropy_nonfocal=-0.0455 (shaper, n_ts=80); organizer +0.0115"
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-TMP-009",
   "what_failed": "Attributing PULL_UP decline to defensive adaptation without accounting for lineup effects.",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); Effect shrinks from -0.0255 to -0.0063 without lineup FE and the same-shooter placebo on other play types is -0.0071/-0.0075, consistent with shooter-level confound."
  },
  {
   "id": "FAM:SF34",
   "what_failed": "Detecting substantial shifts in opponent's shot mix due to a rim big being off the floor.",
   "why": "LIM:small_sample; Sub-1pp mix shifts with PPP t=+1.1; chat verdict WEAK/SMALL, will not carry a paper. Rim share +0.123 with SE 0.295."
  },
  {
   "id": "FAM:SF-APPA-005",
   "what_failed": "Inferring defensive scheme changes from play-by-play data.",
   "why": "A_unanswerable (question not answerable with the data or design); inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise."
  },
  {
   "id": "FAM:SF-TMP-016",
   "what_failed": "Detecting reliable team heterogeneity in halftime play-type adaptation.",
   "why": "A_unanswerable (question not answerable with the data or design); Team-season slope SD 0.6733 vs mean sampling SE 0.6508; split-half r -0.026."
  },
  {
   "id": "FAM:SF-APPS-058",
   "what_failed": "Using NBA matchup/PBP fields to label on-ball defensive coverage at usable rates.",
   "why": "A_unanswerable (question not answerable with the data or design); Confident label rates 14.9% and 3.3%; NBA matchups feed did not populate switches_on."
  }
 ],
 "evidence_establishes": [
  "Lineup composition, defined by player roles (e.g., shaper, organizer), can be characterized and is separable from raw talent counts (FAM:SF-PAP-009).",
  "Changes in offensive personnel, specifically the presence of a 'shaper' or 'organizer', are associated with within-team shifts in play-type mix (e.g., more cuts/PNR, fewer spot-ups/drives with a shaper; more POST_UP with an organizer) (FAM:SF-PAP-007).",
  "Lineup fixed effects are crucial to avoid confounding when studying effects related to play types or shot selection, as failing to include them can lead to spurious 'artifact' effects (FAM:SF-TMP-009).",
  "Opponent lineup changes (e.g., absence of a rim-protecting big) can induce small, but sometimes statistically significant, shifts in offensive shot mix (e.g., more drives, fewer 3-pointers) (FAM:SF34). These effects, however, may be too small to be practically meaningful or reliably detected without very large samples."
 ],
 "evidence_does_not_establish": [
  "The magnitude or reliability of 'personnel effects' on shot mix when the offensive five changes, beyond specific roles or opponent adaptations.",
  "Whether the current data and design can reliably detect these effects with sufficient power to make strong conclusions, especially given the small observed shifts in related studies (FAM:SF34).",
  "A clear methodology for isolating *causal* personnel effects from other confounding factors (e.g., game state, coaching decisions, defensive adjustments) beyond the need for lineup fixed effects.",
  "Whether changes in lineup composition (e.g., one player in/out) are sufficiently frequent and varied to provide enough data points for robust analysis of individual personnel effects on shot mix.",
  "The specific mechanisms through which offensive personnel changes lead to changes in shot mix."
 ],
 "own_inferences": [
  "The research question implies a need for causal inference, which will be challenging due to the endogenous nature of lineup decisions and potential confounding factors.",
  "Measuring 'shot mix' will likely involve analyzing the distribution of shot types (e.g., 3-pointers, mid-range, rim attempts) or play types (e.g., drives, post-ups, spot-ups).",
  "Lineup changes are not random, meaning observational studies will require robust controls, potentially including fixed effects for team, game, and even specific lineup combinations, to mitigate confounding.",
  "The data on play-by-play, substitutions, and derived play types should be sufficient to construct variables for offensive lineups and shot/play mix."
 ],
 "uncertainties": [
  "The specific definition and granularity of 'offensive five' (e.g., any change in one player, or only complete lineup changes?).",
  "How 'shot mix' will be quantified (e.g., proportion of shots from different zones, proportion of different play types, specific shot selection metrics).",
  "The frequency of relevant 'changes in the offensive five' within games and across seasons that are independent enough to allow for robust statistical analysis.",
  "The relative contribution of offensive personnel to shot mix versus defensive scheme adjustments, coaching instructions, or game situation."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence strongly reinforced the importance of accounting for confounding, particularly through lineup fixed effects (FAM:SF-TMP-009), and highlighted the difficulty in detecting subtle effects with sufficient power (FAM:SF34). This evidence shifts the decision from a straightforward 'proceed' to 'proceed_with_changes', emphasizing the need for robust controls, careful definition of the estimand, and a clear understanding of the limitations regarding effect size and testability due to sample size/power concerns. It also provides a positive precedent for observing play-mix shifts due to player roles (FAM:SF-PAP-007)."
 },
 "testability": {
  "p_testable": 0.6,
  "blocking_constraints": []
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": [
   "FAM:SF-PAP-007",
   "FAM:SF34",
   "FAM:SF-TMP-009"
  ],
  "summary": "Previous work shows that player roles in lineups are associated with shifts in play-type mix (FAM:SF-PAP-007). It also indicates that opponent lineup changes can cause small, but potentially detectable, shifts in shot mix (FAM:SF34), though these effects can be weak and suffer from sample size issues. Critically, it establishes that proper controls, such as lineup fixed effects, are essential to avoid confounding and artifactual findings when studying play-type effectiveness and related outcomes (FAM:SF-TMP-009)."
 },
 "risks": [
  {
   "code": "CONFOUNDING",
   "text": "Lineup changes are not random; they are driven by game state, player performance, foul trouble, and coaching strategy. Isolating the 'personnel effect' from these confounding factors will be challenging. Without robust controls (e.g., fixed effects for team, game, opponent, and potentially even specific game states or substitution patterns), observed correlations could be spurious."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "While lineup changes are frequent, specific offensive five combinations might not have enough possessions to reliably estimate their unique effect on shot mix, especially for less common lineups or individual player effects. Previous work on opponent lineup adaptation (FAM:SF34) found effects were small and suffered from power issues despite a large total sample."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "The 'shot mix' metric needs to be precisely defined and its reliability established. Small shifts in shot distribution might be hard to detect reliably, and the 'play-type' labels themselves, while generally robust, can have some noise (e.g., FAM:SF-APPM-021 notes 'OTHER' label noise)."
  },
  {
   "code": "OUTCOME_DERIVED_LABEL",
   "text": "If 'shot mix' is derived from play-by-play data, ensuring its accuracy and consistent definition across different contexts is crucial. Any errors in play-type classification or shot location attribution could impact the reliability of the outcome variable."
  },
  {
   "code": "RTM_SELECTION",
   "text": "Coaches might change lineups in response to recent performance (e.g., a cold streak or a run of bad shots). This could lead to regression to the mean effects being misattributed to the lineup change itself."
  }
 ],
 "predicted_outcome": {
  "supported": 0.4,
  "rejected": 0.2,
  "untestable": 0.1,
  "artifact": 0.2,
  "uncertain": 0.1
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The causal effect of changing the offensive five (defined as a specific 5-player lineup) on the team's shot mix (defined as the proportion of possessions resulting in a shot attempt from the rim, mid-range, or three-point area, and the proportion of possessions ending in specific play types like DRIVE, PNR, SPOT_UP, CUT, POST_UP) in subsequent possessions, controlling for confounding factors.",
  "unit": "Possession-level data, aggregated at the lineup-sequence level (e.g., sequences of possessions for a given offensive five before a substitution or quarter break).",
  "sample": "All NBA 2022-23, 2023-24, and 2024-25 regular season and playoff games. Focus on within-team, within-game lineup changes to maximize controls. Exclude garbage time (large score differentials, late in game). Filter for lineups with a minimum number of possessions (e.g., >50 or >100 per team-season) to ensure sufficient sample size for each lineup combination.",
  "power": "Power analysis will be conducted based on observed variance in shot mix and expected effect sizes from prior work (e.g., FAM:SF34's sub-1pp shifts). The goal is to detect shifts of at least 1 percentage point in shot type proportions. The large dataset (3 seasons of NBA play-by-play) should provide reasonable power for frequently used lineups, but power will be limited for rare combinations.",
  "controls": "Mixed-effects model with fixed effects for: team-game (to control for opponent, game context, coaching strategy), offensive lineup combination (to absorb baseline effects of specific groups), and possibly individual player fixed effects (to control for player-specific tendencies). Include covariates for game state (score differential, time remaining, quarter), recent offensive/defensive performance, and recent play-type usage to mitigate endogeneity. Consider including opponent defensive lineup composition as a control if possible (using defensive matchup data).",
  "falsification": "A falsification test could involve examining whether changing the offensive five affects prior possessions' shot mix (should be null). Another test could be to apply the same methodology to a 'placebo' outcome that should not be affected by offensive personnel changes (e.g., opponent's shot mix in the same possessions).",
  "multiplicity": "Given multiple shot mix components (rim, mid-range, 3-point, various play types), appropriate adjustments for multiple comparisons (e.g., Holm-Bonferroni correction or FDR control) will be applied if testing individual components. Alternatively, a composite shot mix metric could be developed, or a multivariate outcome model used.",
  "decision_rule": "The hypothesis will be considered supported if there are statistically significant (p < 0.05 after multiplicity correction) and practically meaningful (e.g., >1 percentage point shift) changes in at least one key component of shot mix, consistently across a substantial number of lineup changes, with effects robust to various control specifications and passing falsification tests.",
  "data_version": "NBA 2022-23, 2023-24, 2024-25 regular season and playoffs play-by-play, substitution, starters, defensive matchup minutes, box-score summary data, and derived play-type possession records."
 }
}

